/*Table structure for table `sys_acl` */

DROP TABLE IF EXISTS `sys_acl`;

CREATE TABLE `sys_acl` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `tabindex` char(4) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `resource` tinyint(1) NOT NULL COMMENT 'sys_modules',
  `controller` varchar(30) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `route` varchar(20) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `action` varchar(140) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `role` tinyint(2) unsigned NOT NULL COMMENT 'RBACL is hierarchical, hence only role',
  `menu` varchar(100) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `display` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1-Display in Menu, 0-No Display',
  `dashboard` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1-Display in Dashboard, 0-No Display',
  `process` int(11) NOT NULL DEFAULT 0 COMMENT 'sys_process',
  `process_action` int(11) NOT NULL DEFAULT 0 COMMENT 'sys_process_action',
  `description` varchar(100) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `parent_page` int(4) NOT NULL DEFAULT 0 COMMENT 'container page',
  `button_position` int(11) NOT NULL DEFAULT 0 COMMENT 'sys_button_position',
  `icon` varchar(100) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '0' COMMENT 'Button or Menu icon',
  `class` varchar(100) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '0' COMMENT 'Button CSS Class',
  `btn` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1-Yes, 0-No',
  `btn_type` int(4) NOT NULL DEFAULT 0 COMMENT '0-NA, 1-Normal, 2-Modal',
  `btn_label` varchar(50) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '0' COMMENT 'Label for buttons',
  `permission_level` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'sys_status',
  `system` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1-No Access Required, 0-Access Required',
  `author` smallint(2) unsigned DEFAULT 1,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `menu` (`menu`),
  UNIQUE KEY `tabindex` (`tabindex`),
  KEY `role` (`role`)
) ENGINE=InnoDB AUTO_INCREMENT=3132 DEFAULT CHARSET=utf8 COMMENT='acl combines resources, actions and privileges table; InnoDB';

